  drft_lookup l; float x[64], y[64]; int i, k;
  drft_init(&l, n);
  for (i = 0; i < n; i++) x[i] = y[i] = (float)((i * 7 + 3) % 11) - 5.0f;
  drft_forward(&l, y);
  for (k = 0; k <= n / 2; k++) {
    double re = 0, im = 0;
    for (i = 0; i < n; i++) { double a = -6.283185307179586 * k * i / n; re += x[i] * cos(a); im += x[i] * sin(a); }
    double gotre = (k == 0) ? y[0] : y[2 * k - 1];
    if (fabs(gotre - re) > 1e-3) return 0;
    if (k > 0 && 2 * k < n && fabs(y[2 * k] - im) > 1e-3) return 0;
  }
  free(l.trigcache); free(l.splitcache);
  return 1;
}
int main()
{
  drft_lookup one; float v = 3.5f;
  drft_init(&one, 1); drft_forward(&one, &v);
  if (v != 3.5f) { std::printf("00c9bc10_TEST FAIL\n"); return 1; }
  free(one.trigcache); free(one.splitcache);
  if (!check(8) || !check(16) || !check(12) || !check(6) || !check(10) || !check(32) || !check(2)) { std::printf("00c9bc10_TEST FAIL\n"); return 1; }
  std::printf("00c9bc10_TEST PASS\n");
  return 0;
}
